package it.frociart.app;
import java.util.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import static it.frociart.app.FlowModel.*;
public final class ReferenceArrayCoreTests {
 static int checks;static void check(boolean b,String text){if(!b)throw new AssertionError(text);checks++;}static String dec(String s){return new String(Base64.getDecoder().decode(s),StandardCharsets.UTF_8);}
 static void execute(Document d,String[] row){FlowEngine.Runner r=new FlowEngine.Runner(d);int at=0;for(int i=0;i<1500&&r.state!=FlowEngine.State.COMPLETED&&r.state!=FlowEngine.State.ERROR;i++){if(r.state==FlowEngine.State.WAITING){check(!r.submitInput("invalid_input"),"Invalid indexed input retryable");r.submitInput(row[6].split("\\|")[at++]);}else if(r.state==FlowEngine.State.WAITING_FILE)r.provideFile(r.pendingFile(),row[7]);else r.step();}check((r.state==FlowEngine.State.ERROR)==row[5].equals("error"),row[0]+" expected="+row[5]+" actual="+r.state+" "+r.errorMessage);check(r.state==FlowEngine.State.COMPLETED||r.state==FlowEngine.State.ERROR,"Bounded completion");check(r.outputText().replace("\r\n","\n").equals(row[2]),"Output "+row[0]+": "+r.outputText());List<FlowEngine.CallFrameSnapshot> frames=r.callStack();String a=frames.isEmpty()||!frames.get(0).variables.containsKey("a")?"":frames.get(0).variables.get("a").format();check(a.equals(row[3]),"Root reference value "+row[0]+": "+a);}
 public static void main(String[] args)throws Exception{Path root=Paths.get(args[0]);for(String line:Files.readAllLines(root.resolve("cases.tsv"),StandardCharsets.UTF_8)){String[] raw=line.split("\t",-1),row=new String[raw.length];row[0]=raw[0];for(int i=1;i<raw.length;i++)row[i]=dec(raw[i]);Document d=FlowPseudocode.decode(row[1]);if(d.functions!=null)for(Function f:d.functions)for(Parameter p:f.parameters)p.byReference=p.isArray&&(row[4].equals("*")||Arrays.asList(row[4].split("\\|")).contains(f.name+":"+p.name));d.version=FlowFunctions.projectVersion(d.functions);String before=FlowCodec.encode(d);execute(d,row);check(FlowCodec.encode(d).equals(before),"Runtime leaves graph unchanged");execute(d.copy(),row);execute(FlowPseudocode.decode(FlowPseudocode.encode(d)),row);Path save=root.resolve("android-"+row[0]+".frociart");Files.write(save,before.getBytes(StandardCharsets.UTF_8));Document loaded=FlowCodec.decode(new String(Files.readAllBytes(save),StandardCharsets.UTF_8));long flags=d.functions.stream().flatMap(f->f.parameters.stream()).filter(p->p.byReference).count();check(loaded.functions.stream().flatMap(f->f.parameters.stream()).filter(p->p.byReference).count()==flags,"Optional reference flag retained");execute(loaded,row);Document pc=FlowCodec.decode(new String(Files.readAllBytes(root.resolve("pc-"+row[0]+".frociart")),StandardCharsets.UTF_8));execute(pc,row);System.out.println("PASS "+row[0]);}
 Document d=FlowPseudocode.decode("FUNZIONE bump(v: INTERO[])\nv[0]=7\nPAUSA\nv[0]=8\nFINE FUNZIONE\na=[1,2]\nCHIAMA bump(a)");d.functions.get(0).parameters.get(0).byReference=true;d.version=3;FlowEngine.Runner r=new FlowEngine.Runner(d);FlowDebugger debug=new FlowDebugger(r,d);debug.begin(FlowDebugger.Command.CONTINUE);for(int i=0;i<50&&debug.active();i++)debug.tick();check(debug.atBreakpoint(),"Breakpoint in reference call");FlowEngine.CallFrameSnapshot saved=r.callStack().get(0);check(saved.variables.get("a").format().equals("[7, 2]"),"Caller watch updates before return");debug.begin(FlowDebugger.Command.CONTINUE);for(int i=0;i<50&&debug.active();i++)debug.tick();check(r.callStack().get(0).variables.get("a").format().equals("[8, 2]"),"Final reference update visible");check(saved.variables.get("a").format().equals("[7, 2]"),"Previous watch snapshot immutable");System.out.println("REFERENCE_ARRAY_ANDROID_CORE PASS checks="+checks);
 }
}
